import torch, json
from transformers import AutoModelForCausalLM, AutoTokenizer
tok=AutoTokenizer.from_pretrained("gpt2"); m=AutoModelForCausalLM.from_pretrained("gpt2").eval()
D=json.load(open("big.json")); S=json.load(open("sets.json"))
LAYERS=[4,5,6,7,8]
X={}
def mk(L):
    def h(mod,inp): X[L]=inp[0].detach()
    return h
for L in LAYERS: m.transformer.h[L].mlp.register_forward_pre_hook(mk(L))
def ent(p): return ("2022" in p) and ("World Cup" in p) and not any(w in p for w in ["Club World","Rugby World","Cricket World"])
def crit(p,ids):
    toks=[tok.decode(t).strip() for t in ids]
    if "2022" not in toks or "Cup" not in toks: return None
    return max(toks.index("2022"), max(i for i,t in enumerate(toks) if t=="Cup" and i>0 and toks[i-1]=="World"))
out={}
for split in ["tr","te"]:
    P=[];N=[];Pl=[]
    prompts=D["pos_"+split]+D["neg_"+split]+(S["P_tr"]+S["N_tr"] if split=="tr" else S["P_te"]+S["N_te"])
    for p in prompts:
        ids=tok(p,return_tensors="pt").input_ids[0]
        with torch.no_grad(): m(ids[None])
        if ent(p):
            c=crit(p,ids)
            if c is None: print("nocrit",p); continue
            P.append(torch.stack([X[L][0,c] for L in LAYERS])); Pl.append(p)
            for i in range(c): N.append(torch.stack([X[L][0,i] for L in LAYERS]))
        else:
            for i in range(len(ids)): N.append(torch.stack([X[L][0,i] for L in LAYERS]))
    out[split]=dict(P=torch.stack(P,1),N=torch.stack(N,1),Pl=Pl)
    print(split,len(P),len(N))
K=torch.load("xkeys.pt")
out["gen"]=K["gen"][LAYERS]
out["LAYERS"]=LAYERS
torch.save(out,"subj.pt")
'

